def test_resource_warning(pytester: Pytester, monkeypatch: pytest.MonkeyPatch) -> None:
    # Some platforms (notably PyPy) don't have tracemalloc.
    # We choose to explicitly not skip this in case tracemalloc is not
    # available, using `importorskip("tracemalloc")` for example,
    # because we want to ensure the same code path does not break in those platforms.
    try:
        import tracemalloc  # noqa: F401

        has_tracemalloc = True
    except ImportError:
        has_tracemalloc = False

    # Explicitly disable PYTHONTRACEMALLOC in case pytest's test suite is running
    # with it enabled.
    monkeypatch.delenv("PYTHONTRACEMALLOC", raising=False)

    pytester.makepyfile(
        """
        def open_file(p):
            f = p.open("r", encoding="utf-8")
            assert p.read_text() == "hello"

        def test_resource_warning(tmp_path):
            p = tmp_path.joinpath("foo.txt")
            p.write_text("hello", encoding="utf-8")
            open_file(p)
        """
    )
    result = pytester.run(sys.executable, "-Xdev", "-m", "pytest")
    expected_extra = (
        [
            "*ResourceWarning* unclosed file*",
            "*Enable tracemalloc to get traceback where the object was allocated*",
            "*See https* for more info.",
        ]
        if has_tracemalloc
        else []
    )
    result.stdout.fnmatch_lines([*expected_extra, "*1 passed*"])

    monkeypatch.setenv("PYTHONTRACEMALLOC", "20")

    result = pytester.run(sys.executable, "-Xdev", "-m", "pytest")
    expected_extra = (
        [
            "*ResourceWarning* unclosed file*",
            "*Object allocated at*",
        ]
        if has_tracemalloc
        else []
    )
    result.stdout.fnmatch_lines([*expected_extra, "*1 passed*"])


class TestMaxWarnings:
    """Tests for the --max-warnings feature."""

    PYFILE = """
        import warnings
        def test_one():
            warnings.warn(UserWarning("warning one"))
        def test_two():
            warnings.warn(UserWarning("warning two"))
    """

    @pytest.mark.filterwarnings("default::UserWarning")
    def test_max_warnings_not_set(self, pytester: Pytester) -> None:
        """Without --max-warnings, warnings don't affect exit code."""
        pytester.makepyfile(self.PYFILE)
        result = pytester.runpytest()
        result.assert_outcomes(passed=2, warnings=2)
        assert result.ret == ExitCode.OK

    @pytest.mark.filterwarnings("default::UserWarning")
    def test_max_warnings_not_exceeded(self, pytester: Pytester) -> None:
        """When warning count is below the threshold, exit code is OK."""
        pytester.makepyfile(self.PYFILE)
        result = pytester.runpytest("--max-warnings", "10")
        result.assert_outcomes(passed=2, warnings=2)
        assert result.ret == ExitCode.OK

    @pytest.mark.filterwarnings("default::UserWarning")
    def test_max_warnings_exceeded(self, pytester: Pytester) -> None:
        """When warning count exceeds threshold, exit code is MAX_WARNINGS_ERROR."""
        pytester.makepyfile(self.PYFILE)
        result = pytester.runpytest("--max-warnings", "1")
        assert result.ret == ExitCode.MAX_WARNINGS_ERROR

    @pytest.mark.filterwarnings("default::UserWarning")
    def test_max_warnings_equal_to_count(self, pytester: Pytester) -> None:
        """When warning count equals threshold exactly, exit code is OK."""
        pytester.makepyfile(self.PYFILE)
        result = pytester.runpytest("--max-warnings", "2")
        result.assert_outcomes(passed=2, warnings=2)
        assert result.ret == ExitCode.OK

    @pytest.mark.filterwarnings("default::UserWarning")
    def test_max_warnings_zero(self, pytester: Pytester) -> None:
        """--max-warnings 0 means no warnings are allowed."""
        pytester.makepyfile(self.PYFILE)
        result = pytester.runpytest("--max-warnings", "0")
        assert result.ret == ExitCode.MAX_WARNINGS_ERROR

    @pytest.mark.filterwarnings("default::UserWarning")
    def test_max_warnings_exceeded_message(self, pytester: Pytester) -> None:
        """Verify the output message when max warnings is exceeded."""
        pytester.makepyfile(self.PYFILE)
        result = pytester.runpytest("--max-warnings", "1")
        result.stdout.fnmatch_lines(
            ["*Tests pass, but maximum allowed warnings exceeded: 2 > 1*"]
        )

    @pytest.mark.filterwarnings("default::UserWarning")
    def test_max_warnings_ini_option(self, pytester: Pytester) -> None:
        """max_warnings can be set via INI configuration."""
        pytester.makeini(
            """
            [pytest]
            max_warnings = 1
            """
        )
        pytester.makepyfile(self.PYFILE)
        result = pytester.runpytest()
        assert result.ret == ExitCode.MAX_WARNINGS_ERROR

    @pytest.mark.filterwarnings("default::UserWarning")
    @pytest.mark.parametrize("value", ["1", '"1"'])
    def test_max_warnings_toml_option(self, pytester: Pytester, value: str) -> None:
        """max_warnings can be set via TOML configuration.

        Supports both int and str (for backward compat).
        """
        pytester.maketoml(
            f"""
            [pytest]
            max_warnings = {value}
            """
        )
        pytester.makepyfile(self.PYFILE)
        result = pytester.runpytest()
        assert result.ret == ExitCode.MAX_WARNINGS_ERROR

    @pytest.mark.filterwarnings("default::UserWarning")
    def test_max_warnings_with_test_failure(self, pytester: Pytester) -> None:
        """When tests fail AND warnings exceed max, TESTS_FAILED takes priority."""
        pytester.makepyfile(
            """
            import warnings
            def test_fail():
                warnings.warn(UserWarning("a warning"))
                assert False
            """
        )
        result = pytester.runpytest("--max-warnings", "0")
        assert result.ret == ExitCode.TESTS_FAILED

    @pytest.mark.filterwarnings("default::UserWarning")
    def test_max_warnings_with_filterwarnings_ignore(self, pytester: Pytester) -> None:
        """Filtered (ignored) warnings don't count toward max_warnings."""
        pytester.makepyfile(
            """
            import warnings
            def test_one():
                warnings.warn(UserWarning("counted"))
                warnings.warn(RuntimeWarning("ignored"))
            """
        )
        result = pytester.runpytest(
            "--max-warnings",
            "1",
            "-W",
            "ignore::RuntimeWarning",
        )
        result.assert_outcomes(passed=1, warnings=1)
        assert result.ret == ExitCode.OK

    @pytest.mark.filterwarnings("default::UserWarning")
    def test_max_warnings_with_filterwarnings_error(self, pytester: Pytester) -> None:
        """Warnings turned into errors via filterwarnings don't count as warnings."""
        pytester.makepyfile(
            """
            import warnings
            def test_one():
                warnings.warn(UserWarning("still a warning"))
            def test_two():
                warnings.warn(RuntimeWarning("becomes an error"))
            """
        )
        result = pytester.runpytest(
            "--max-warnings",
            "0",
            "-W",
            "error::RuntimeWarning",
        )
        # The RuntimeWarning becomes a test error, so TESTS_FAILED takes priority.
        assert result.ret == ExitCode.TESTS_FAILED

    @pytest.mark.filterwarnings("default::UserWarning")
    def test_max_warnings_with_filterwarnings_ini_ignore(
        self, pytester: Pytester
    ) -> None:
        """Warnings ignored via ini filterwarnings don't count toward max_warnings."""
        pytester.makeini(
            """
            [pytest]
            filterwarnings =
                ignore::RuntimeWarning
            max_warnings = 1
            """
        )
        pytester.makepyfile(
            """
            import warnings
            def test_one():
                warnings.warn(UserWarning("counted"))
                warnings.warn(RuntimeWarning("ignored by ini"))
            """
        )
        result = pytester.runpytest()
        result.assert_outcomes(passed=1, warnings=1)
        assert result.ret == ExitCode.OK


def test_pythonwarnings_not_duplicated(pytester: Pytester) -> None:
    """Regression test for #13484: -W values should not be duplicated in
    known_args_namespace due to the arg parser being called multiple times."""
    config = pytester.parseconfig("-W", "error")
    warnings_list = config.known_args_namespace.pythonwarnings
    assert warnings_list is not None
    assert warnings_list == ["error"]

"""Test importing of all internal packages and modules.

This ensures all internal packages can be imported without needing the pytest
namespace being set, which is critical for the initialization of xdist.
"""

from __future__ import annotations

import pkgutil
import subprocess
import sys

import _pytest
import pytest


def _modules() -> list[str]:
    pytest_pkg: str = _pytest.__path__  # type: ignore
    return sorted(
        n
        for _, n, _ in pkgutil.walk_packages(pytest_pkg, prefix=_pytest.__name__ + ".")
    )


@pytest.mark.slow
@pytest.mark.parametrize("module", _modules())
def test_no_warnings(module: str) -> None:
    # fmt: off
    subprocess.check_call((
        sys.executable,
        "-W", "error",
        "-c", f"__import__({module!r})",
    ))
    # fmt: on

from __future__ import annotations

from _pytest.pytester import Pytester


def test_show_fixtures_and_test(
    pytester: Pytester, dummy_yaml_custom_test: None
) -> None:
    """Verify that fixtures are not executed."""
    pytester.makepyfile(
        """
        import pytest
        @pytest.fixture
        def arg():
            assert False
        def test_arg(arg):
            assert False
    """
    )

    result = pytester.runpytest("--setup-plan")
    assert result.ret == 0

    result.stdout.fnmatch_lines(
        ["*SETUP    F arg*", "*test_arg (fixtures used: arg)", "*TEARDOWN F arg*"]
    )


def test_show_multi_test_fixture_setup_and_teardown_correctly_simple(
    pytester: Pytester,
) -> None:
    """Verify that when a fixture lives for longer than a single test, --setup-plan
    correctly displays the SETUP/TEARDOWN indicators the right number of times.

    As reported in https://github.com/pytest-dev/pytest/issues/2049
    --setup-plan was showing SETUP/TEARDOWN on every test, even when the fixture
    should persist through multiple tests.

    (Note that this bug never affected actual test execution, which used the
    correct fixture lifetimes. It was purely a display bug for --setup-plan, and
    did not affect the related --setup-show or --setup-only.)
    """
    pytester.makepyfile(
        """
        import pytest
        @pytest.fixture(scope = 'class')
        def fix():
            return object()
        class TestClass:
            def test_one(self, fix):
                assert False
            def test_two(self, fix):
                assert False
    """
    )

    result = pytester.runpytest("--setup-plan")
    assert result.ret == 0

    setup_fragment = "SETUP    C fix"
    setup_count = 0

    teardown_fragment = "TEARDOWN C fix"
    teardown_count = 0

    for line in result.stdout.lines:
        if setup_fragment in line:
            setup_count += 1
        if teardown_fragment in line:
            teardown_count += 1

    # before the fix this tests, there would have been a setup/teardown
    # message for each test, so the counts would each have been 2
    assert setup_count == 1
    assert teardown_count == 1


def test_show_multi_test_fixture_setup_and_teardown_same_as_setup_show(
    pytester: Pytester,
) -> None:
    """Verify that SETUP/TEARDOWN messages match what comes out of --setup-show."""
    pytester.makepyfile(
        """
        import pytest
        @pytest.fixture(scope = 'session')
        def sess():
            return True
        @pytest.fixture(scope = 'module')
        def mod():
            return True
        @pytest.fixture(scope = 'class')
        def cls():
            return True
        @pytest.fixture(scope = 'function')
        def func():
            return True
        def test_outside(sess, mod, cls, func):
            assert True
        class TestCls:
            def test_one(self, sess, mod, cls, func):
                assert True
            def test_two(self, sess, mod, cls, func):
                assert True
    """
    )

    plan_result = pytester.runpytest("--setup-plan")
    show_result = pytester.runpytest("--setup-show")

    # the number and text of these lines should be identical
    plan_lines = [
        line
        for line in plan_result.stdout.lines
        if "SETUP" in line or "TEARDOWN" in line
    ]
    show_lines = [
        line
        for line in show_result.stdout.lines
        if "SETUP" in line or "TEARDOWN" in line
    ]

    assert plan_lines == show_lines

# mypy: allow-untyped-defs
"""Test correct setup/teardowns at module, class, and instance level."""

from __future__ import annotations

from _pytest.pytester import Pytester
import pytest


def test_module_and_function_setup(pytester: Pytester) -> None:
    reprec = pytester.inline_runsource(
        """
        modlevel = []
        def setup_module(module):
            assert not modlevel
            module.modlevel.append(42)

        def teardown_module(module):
            modlevel.pop()

        def setup_function(function):
            function.answer = 17

        def teardown_function(function):
            del function.answer

        def test_modlevel():
            assert modlevel[0] == 42
            assert test_modlevel.answer == 17

        class TestFromClass(object):
            def test_module(self):
                assert modlevel[0] == 42
                assert not hasattr(test_modlevel, 'answer')
    """
    )
    rep = reprec.matchreport("test_modlevel")
    assert rep.passed
    rep = reprec.matchreport("test_module")
    assert rep.passed


def test_module_setup_failure_no_teardown(pytester: Pytester) -> None:
    reprec = pytester.inline_runsource(
        """
        values = []
        def setup_module(module):
            values.append(1)
            0/0

        def test_nothing():
            pass

        def teardown_module(module):
            values.append(2)
    """
    )
    reprec.assertoutcome(failed=1)
    calls = reprec.getcalls("pytest_runtest_setup")
    assert calls[0].item.module.values == [1]


