from __future__ import annotations

from dataclasses import dataclass
from dataclasses import field


def test_comparing_two_different_data_classes() -> None:
    @dataclass
    class SimpleDataObjectOne:
        field_a: int = field()
        field_b: str = field()

    @dataclass
    class SimpleDataObjectTwo:
        field_a: int = field()
        field_b: str = field()

    left = SimpleDataObjectOne(1, "b")
    right = SimpleDataObjectTwo(1, "c")

    assert left != right  # type: ignore[comparison-overlap]

from __future__ import annotations

from dataclasses import dataclass
from dataclasses import field


def test_dataclasses() -> None:
    @dataclass
    class SimpleDataObject:
        field_a: int = field()
        field_b: str = field()

        def __eq__(self, o: object, /) -> bool:
            return super().__eq__(o)

    left = SimpleDataObject(1, "b")
    right = SimpleDataObject(1, "c")

    assert left == right

# mypy: allow-untyped-defs
from __future__ import annotations

from dataclasses import dataclass


@dataclass
class S:
    a: int
    b: str


@dataclass
class C:
    c: S
    d: S


@dataclass
class C2:
    e: C
    f: S


@dataclass
class C3:
    g: S
    h: C2
    i: str
    j: str


def test_recursive_dataclasses():
    left = C3(
        S(10, "ten"),
        C2(C(S(1, "one"), S(2, "two")), S(2, "three")),
        "equal",
        "left",
    )
    right = C3(
        S(20, "xxx"),
        C2(C(S(1, "one"), S(2, "yyy")), S(3, "three")),
        "equal",
        "right",
    )

    assert left == right

